#!/bin/bash

# cleanup
rm -rf obj_dir
rm -f *.vcd

# run Verilator to translate Verilog into C++, including C++ testbench
verilator -Wall --cc --trace --top-module f1_fsm --prefix Vdut f1_fsm.sv --exe f1_fsm_tb.cpp

# build C++ project via make automatically generated by Verilator
make -j -C obj_dir/ -f Vdut.mk Vdut

cp -r vbuddy.cfg obj_dir
cp -r vbuddy.cpp obj_dir

# run executable file simulation
obj_dir/Vdut
